sp_widget.client_script:
api.controller = function($scope) {
  var c = this;
  c.open = false;
  c.submitted = false;
  c.error = '';
  c.form = {};

  c.submit = function() {
    if (!c.form.patient_name) {
      c.error = 'Please enter your name.';
      return;
    }
    c.error = '';
    c.server.get({
      action: 'submit',
      patient_name: c.form.patient_name,
      experience_with_doctor: c.form.experience_with_doctor,
      overall_experience: c.form.overall_experience,
      rate_the_facilities: c.form.rate_the_facilities,
      comments: c.form.comments
    }).then(function(response) {
      if (response.data.success) {
        c.submitted = true;
        c.form = {};
      } else {
        c.error = 'Could not save. Please try again.';
      }
    });
  };

  c.close = function() {
    c.open = false;
    c.submitted = false;
    c.error = '';
  };
};

sp_widget.css:
.fb-btn {
  position: fixed;
  right: 0;
  top: 50%;
  transform: rotate(-90deg) translateX(50%);
  transform-origin: right bottom;
  background: #1f8476;
  color: #fff;
  border: none;
  padding: 8px 20px;
  z-index: 999;
  cursor: pointer;
}
.fb-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(0,0,0,0.5);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
}
.fb-modal {
  background: #fff;
  padding: 20px;
  width: 420px;
  max-width: 90%;
  max-height: 90vh;
  overflow-y: auto;
  border-radius: 8px;
}
.fb-modal label { font-weight: 600; margin-top: 6px; }
.fb-modal .form-control { margin-bottom: 8px; }
.fb-actions { text-align: right; margin-top: 10px; }

sp_widget.script:
(function() {
  if (input && input.action == 'submit') {
    var gr = new GlideRecord('x_snc_discharge_0_feedback');
    gr.initialize();
    gr.setValue('patient_name', input.patient_name);
    gr.setValue('experience_with_doctor', input.experience_with_doctor);
    gr.setValue('overall_experience', input.overall_experience);
    gr.setValue('rate_the_facilities', input.rate_the_facilities);
    gr.setValue('comments', input.comments);
    var sysId = gr.insert();
    data.success = !!sysId;
  }
})();
